CREATE TABLE win14_months (month_no INTEGER PRIMARY KEY, revenue INTEGER NOT NULL);
INSERT INTO win14_months VALUES (1, 100), (2, 130), (3, 120), (4, 160);
SELECT month_no, revenue, LAG(revenue) OVER (ORDER BY month_no) AS previous_revenue FROM win14_months ORDER BY month_no;

